"""Where the merit-order model's night error (00:00-06:00) comes from (notes 21.28): load forecast against published load, night by night."""
import numpy as np, pandas as pd, warnings; warnings.filterwarnings("ignore")
import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
SP = "/tmp/claude-0/-home-user-EpexPredictor/d6125cc0-c431-5b93-a06f-0110cd871ab6/scratchpad"; CR = {"winter": "hw2", "summer": "hs2", "autumn": "ha"}; SL = slice(0, 24); BLUE, ORANGE, AQUA, INK, MUTED, SURF, GRID, NEUT = "#2a78d6", "#eb6834", "#1baf7a", "#0b0b0b", "#52514e", "#fcfcfb", "#e9e8e3", "#a8a79f"; LB, LO = "#a9c9ef", "#f7c3ad"
plt.rcParams.update({"font.size": 9, "axes.edgecolor": "#c9c8c2", "axes.labelcolor": MUTED, "xtick.color": MUTED, "ytick.color": MUTED, "figure.facecolor": SURF, "axes.facecolor": SURF, "savefig.facecolor": SURF, "font.family": "DejaVu Sans"})
def fin(ax, t, grid="both"):
    ax.grid(True, axis=grid, color=GRID, linewidth=0.6); ax.set_axisbelow(True); [ax.spines[s].set_visible(False) for s in ("top", "right")]; ax.set_title(t, loc="left", fontsize=9.5, fontweight="bold", color=INK)
fig, axs = plt.subplots(1, 4, figsize=(18.5, 4.9), gridspec_kw=dict(wspace=0.28)); T = {}; pool = []
for per in CR:
    I = np.load(f"{SP}/out/inputs_{per}.npz"); a = I["actual"].astype(float); m = np.load(f"{SP}/out/structfc_m1g_{per}_price.npz"); ck = np.load(f"{SP}/out/structfc_{CR[per]}_known_dyn2xxh.npz")["vint"].astype(float); ct = np.load(f"{SP}/out/structfc_{CR[per]}_ts_dyn2xxh.npz")["vint"].astype(float); G = np.load(f"{SP}/out/gen_ts_{per}.npz")
    mae = lambda v: float(np.abs(v - a)[:, SL].mean()); T[per] = (mae(m["vint"]), mae(m["vint_ts"]), mae(ck), mae(ct)); lf = (G["rl_pes"].astype(float) - I["rl_true"].astype(float))[:, SL].mean(1); dp = (m["vint_ts"].astype(float) - m["vint"].astype(float))[:, SL].mean(1); pool.append((per, lf, dp, (m["vint_ts"] - a)[:, SL].mean(1), (ct - a)[:, SL].mean(1), pd.to_datetime([str(c)[:10] for c in I["cutoffs"]]), np.abs(lf).mean()))
    print(per, "night MAE: merit order published / Timestral load", T[per][:2], "candidate's curve", T[per][2:], "| mean |load forecast error| at night", round(float(np.abs(lf).mean()), 2), "GW")
ax = axs[0]; x = np.arange(3); w = 0.19
for j, (lab, col) in enumerate((("merit order, published load given", LB), ("merit order, Timestral's load", BLUE), ("candidate's curve, published load given", LO), ("candidate's curve, Timestral's load", ORANGE))):
    v = [T[p][j] for p in CR]; ax.bar(x + (j - 1.5) * (w + 0.015), v, w, color=col, linewidth=0, label=lab); [ax.text(xi + (j - 1.5) * (w + 0.015), a_ + 0.02, f"{a_:.2f}", ha="center", fontsize=7.5, color=INK) for xi, a_ in zip(x, v)]
ax.set_xticks(x); ax.set_xticklabels(list(CR)); ax.set_ylim(0, 2.4); ax.set_ylabel("MAE 00:00-06:00, ct/kWh"); ax.legend(frameon=False, fontsize=7.5, loc="upper left"); g = [T[p][1] - T[p][0] for p in CR]; fin(ax, f"The load forecast costs the merit order\n{g[0]:.2f}, {g[1]:.2f}, {g[2]:.2f} ct of its night error", "y")
ax = axs[1]; LF = np.concatenate([p[1] for p in pool]); DP = np.concatenate([p[2] for p in pool]); b = np.polyfit(LF, DP, 1)
for (per, lf, dp, *_), col in zip(pool, (NEUT, BLUE, ORANGE)): ax.scatter(lf, dp, s=18, color=col, alpha=0.7, linewidths=0, label=per)
xx = np.linspace(LF.min(), LF.max(), 10); ax.plot(xx, np.polyval(b, xx), color=INK, linewidth=1); ax.axhline(0, color=INK, linewidth=0.5); ax.axvline(0, color=INK, linewidth=0.5); ax.set_xlabel("Timestral's load forecast minus published load, night mean, GW"); ax.set_ylabel("change in the forecast price, ct/kWh"); ax.legend(frameon=False, fontsize=8); fin(ax, f"Each GW of load forecast error moves\nthe night price forecast by {b[0]:.2f} ct")
ax = axs[2]; per, lf, dp, em, ec, d, _ = pool[2]; ax.plot(d, ec, color=ORANGE, linewidth=1.4, label="candidate's curve + layer"); ax.plot(d, em, color=BLUE, linewidth=1.4, label="merit order + layer"); ax.axhline(0, color=INK, linewidth=0.6); ax.set_ylabel("forecast minus actual, night mean, ct/kWh"); ax.legend(frameon=False, fontsize=8, loc="lower left"); ax.tick_params(axis="x", labelrotation=30); fin(ax, f"Autumn, night by night: the two models\nerr together (correlation {np.corrcoef(em, ec)[0, 1]:.2f})")
ax = axs[3]; per, lf, dp, em, ec, d, _ = pool[1]; ax.plot(d, ec, color=ORANGE, linewidth=1.4, label="candidate's curve + layer"); ax.plot(d, em, color=BLUE, linewidth=1.4, label="merit order + layer"); ax.axhline(0, color=INK, linewidth=0.6); ax.set_ylabel("forecast minus actual, night mean, ct/kWh"); ax.legend(frameon=False, fontsize=8, loc="lower left"); ax.tick_params(axis="x", labelrotation=30); fin(ax, f"Summer: the same (correlation {np.corrcoef(em, ec)[0, 1]:.2f});\nmerit order low by {-em.mean():.2f} ct on average")
fig.suptitle("Key metric, 00:00-06:00 one day ahead: where the merit-order model's night error comes from", x=0.125, ha="left", fontsize=11, fontweight="bold", color=INK, y=1.04); fig.savefig(f"{SP}/out/key_diag.png", dpi=105, bbox_inches="tight"); print("figure ok")
